const basePatient=patients;patients=async function(n){await basePatient(n);if(n!==epoch)return;const el=document.createElement('div');el.className='pad';const cs=(await raw('cultures')).filter(c=>c.patient_id===pid),ids=new Set(cs.map(c=>c.culture_id)),is=(await raw('isolates')).filter(i=>ids.has(i.culture_id));if(n!==epoch)return;el.innerHTML=`<button id="open-directory">← ${t('Search patient directory','Hae potilasluettelosta')}</button>`+card(t('Recorded findings for review','Kirjatut löydökset tarkistettavaksi'),`<div class="pad"><p>${t('Positive blood cultures','Positiiviset veriviljelyt')}: <b>${cs.filter(c=>c.specimen==='blood'&&c.result==='positive').length}</b></p><p>${t('Samples ≥2 days after admission','Näytteet ≥2 päivää sisäänoton jälkeen')}: <b>${cs.filter(c=>c.admission_date&&Date.parse(c.sample_date)-Date.parse(c.admission_date)>=172800000).length}</b></p><p>${['esbl','mrsa','vre','cpe'].map(k=>`${k.toUpperCase()}: <b>${is.filter(i=>String(i[k])==='1').length}</b>`).join(' · ')}</p><p class="sub">${t('Counts of recorded findings, not a disease probability or severity score. Timing alone does not establish hospital-acquired infection.','Kirjattujen löydösten määriä, ei sairauden todennäköisyyttä tai vakavuuspisteitä. Ajoitus yksin ei osoita sairaalainfektiota.')}</p></div>`);$('#content').prepend(el);$('#open-directory').onclick=()=>go('directory');};
const enhancedImages=images;images=function(){enhancedImages();const el=document.createElement('div');el.className='pad';el.innerHTML=`<label>${t('Known calibration · µm per original pixel','Tunnettu kalibrointi · µm alkuperäistä pikseliä kohti')} <input id="pixel-scale" type="number" min="0" step="any" placeholder="${t('Uncalibrated','Kalibroimaton')}"></label><p>${t('Click two points in the image to measure their distance. Supply a known pixel scale only if available from your image acquisition.','Mittaa etäisyys napsauttamalla kuvasta kahta pistettä. Anna tunnettu pikseliasteikko vain, jos se on saatavilla kuvan tallennustiedoista.')}</p><output id="line-distance"></output>`;$('#content').append(el);let first=null,distance=null;const show=()=>{const scale=+$('#pixel-scale').value;$('#line-distance').textContent=distance===null?'':`${distance.toFixed(2)} px${scale>0?' · '+(distance*scale).toFixed(2)+' µm':''}`;};$('#microscope').onclick=e=>{const c=e.currentTarget,b=c.getBoundingClientRect(),p={x:(e.clientX-b.left)*c.width/b.width,y:(e.clientY-b.top)*c.height/b.height};if(!first){first=p;$('#line-distance').textContent=t('First point selected. Click the second point.','Ensimmäinen piste valittu. Napsauta toista pistettä.');}else{distance=Math.hypot(p.x-first.x,p.y-first.y);first=null;show();}};$('#pixel-scale').oninput=()=>{show();objectStats=[];};const upload=$('#image-upload').onchange;$('#image-upload').onchange=e=>{$('#pixel-scale').value='';first=null;distance=null;show();upload(e);};};
const baseMeasureObjects=measureObjects;measureObjects=function(){baseMeasureObjects();if(!$('#threshold-on').checked)return;const scale=+($('#pixel-scale')?.value||0),total=objectStats.reduce((s,r)=>s+r.area_pixels,0),c=$('#microscope');if(scale>0)objectStats=objectStats.map(r=>({...r,area_um2:r.area_pixels*scale*scale,calibration_um_per_pixel:scale}));const el=document.createElement('p');el.textContent=`${t('Segmented coverage','Segmentoitu peitto')}: ${percent(total/(c.width*c.height))} · ${t('Mean region area','Alueen keskimääräinen pinta-ala')}: ${objectStats.length?(total/objectStats.length).toFixed(2):0} px²${scale>0?' · '+t('CSV includes calibrated areas.','CSV sisältää kalibroidut pinta-alat.'):''}`;$('#image-measurements').prepend(el);};
